"use client";
import {useState} from 'react';import{createClient}from '@/lib/supabase/client';
export default function ForgotPasswordPage(){const[email,setEmail]=useState(''),[msg,setMsg]=useState(''),[busy,setBusy]=useState(false);async function submit(e:React.FormEvent){e.preventDefault();setBusy(true);const{error}=await createClient().auth.resetPasswordForEmail(email,{redirectTo:`${window.location.origin}/auth/reset-password`});setMsg(error?error.message:'If an account exists for that email, a recovery link has been sent.');setBusy(false);}return <main className="auth-page"><div className="auth-card"><div className="eyebrow">Account recovery</div><h1>Reset your password.</h1><p className="muted">We’ll send a secure recovery link through Supabase Auth.</p><form onSubmit={submit} className="auth-form"><label htmlFor="email">Email</label><input id="email" type="email" required value={email} onChange={e=>setEmail(e.target.value)} placeholder="you@example.com"/><button className="primary-button" disabled={busy}>{busy?'Sending…':'Send recovery link'}</button></form>{msg&&<p className="auth-message" role="status">{msg}</p>}</div></main>}
